#!/usr/bin/env bash
# ============================================================
# PKI Script - remove-pki-ca.sh  (STANDALONE: needs no other script)
# Author : Nicko Satria Utama   Company: Agantra Inovatif OU (NextMantra)   Email: nicko@nextmantra.com
# ============================================================
# Takes PKIs away again that install-pki-ca.sh put on this Linux machine: one company, several, or all.  Run:  ./remove-pki-ca.sh --help
# >>> PKI-VERSION-INFO (generated by tools/update_version_block.py - do not edit here, edit the tool source)
PKI_VER_NUMBER='7.5.3'
PKI_VER_DATE='2026-10-21'
pki_version_info() {
  # --version: the same report in every script (.ps1 and .sh). Plain text, 100 columns, no changes to the system.
  set +e +u +o pipefail 2>/dev/null
  local rule dash name uname_s kind osname osver patch arch platform id vid pretty rel maj ok
  rule="$(printf '%100s' '' | tr ' ' '=')"; dash="$(printf '%100s' '' | tr ' ' '-')"
  _row() { local label="$1" value="$2" first rest; first="${value%%$'\n'*}"; printf ' %-15s: %s\n' "$label" "$first"
           if [ "$value" != "$first" ]; then rest="${value#*$'\n'}"; printf '%s\n' "$rest" | while IFS= read -r l; do printf '%18s%s\n' '' "$l"; done; fi; }
  _run() { timeout 8 "$@" 2>&1 | tr -d '\000'; }
  _first() { printf '%s\n' "$1" | head -n1 | sed 's/[[:space:]]*$//'; }
  _find() { type -ap "$1" 2>/dev/null | awk '!s[$0]++'; }
  _key() { printf '%s\n' "$1" | sed -E 's/^([0-9]+(\.[0-9]+){0,3}).*/\1/'; }
  uname_s="${PKI_FAKE_UNAME:-$(uname -s 2>/dev/null)}"
  arch="$(uname -m 2>/dev/null)"; case "$arch" in x86_64) arch=X64 ;; aarch64|arm64) arch=Arm64 ;; i?86) arch=X86 ;; esac
  kind=other; osname="$uname_s"; osver=''; patch=''; platform='NOT supported'
  if [ "$uname_s" = Darwin ]; then
    kind=macos; osname=macOS; platform='REJECTED (macOS is not supported)'
  elif [ "$uname_s" = Linux ]; then
    kind=linux; rel="${PKI_OS_RELEASE_FILE:-/etc/os-release}"; id=''; vid=''; pretty=''
    if [ -r "$rel" ]; then id="$( . "$rel"; echo "${ID:-}")"; vid="$( . "$rel"; echo "${VERSION_ID:-}")"; pretty="$( . "$rel"; echo "${PRETTY_NAME:-}")"; fi
    osname="${pretty:-Linux}"; osver="$vid"; patch="kernel $(uname -r 2>/dev/null)"
    maj="${vid%%.*}"; case "$maj" in ''|*[!0-9]*) maj=0 ;; esac; ok=0
    case "$id" in ubuntu) [ "$maj" -ge 24 ] && ok=1 ;; centos|rhel|rocky|ol) [ "$maj" -ge 10 ] && ok=1 ;; sles|sles_sap|sled|opensuse-leap) [ "$maj" -ge 15 ] && ok=1 ;; opensuse-tumbleweed) ok=1 ;; esac
    if [ "$ok" = 1 ]; then platform='supported: full (Classic and Quantum)'; else platform='NOT supported (see the platform list in the manual)'; fi
  fi
  name="$(basename "$0")"
  echo "$rule"; echo " $name  -  version information"; echo "$rule"
  echo ' SCRIPT'
  _row Name "$name"
  _row Version "$PKI_VER_NUMBER   (build of $PKI_VER_DATE)"
  _row Author 'Nicko Satria Utama'
  _row Company 'Agantra Inovatif OÜ (NextMantra)'
  _row Email 'nicko@nextmantra.com'
  echo "$dash"; echo ' OPERATING SYSTEM'
  _row Name "$osname"
  [ -n "$osver" ] && _row Version "$osver"
  [ -n "$patch" ] && _row Patch/kernel "$patch"
  [ -n "$arch" ] && _row Architecture "$arch"
  _row Platform "$platform"
  if [ "$kind" = macos ]; then echo "$dash"; echo ' macOS is rejected by these scripts. Nothing else is checked.'; echo "$rule"; return 5; fi

  echo "$dash"; echo ' .NET'
  local dn sdks rts first rest
  dn="$(_find dotnet | head -n1)"
  if [ -n "$dn" ]; then
    sdks="$(_run "$dn" --list-sdks | awk '/^[0-9]+\.[0-9]+\.[0-9]+/ {print $1}' | sort -rV)"
    rts="$(_run "$dn" --list-runtimes | awk '/^Microsoft\./ {sub(/^Microsoft\./,"",$1); print $1, $2}' | sort -k1,1 -k2,2Vr | awk '!s[$1]++ {print $1" "$2}')"
    if [ -n "$sdks" ]; then first="$(printf '%s\n' "$sdks" | head -n1)"; rest="$(printf '%s\n' "$sdks" | tail -n +2 | paste -sd, - | sed 's/,/, /g')"
      if [ -n "$rest" ]; then _row 'SDK (latest)' "$first   (also $rest)"; else _row 'SDK (latest)' "$first"; fi
    else _row 'SDK (latest)' 'none installed'; fi
    if [ -n "$rts" ]; then _row Runtime "$rts"; else _row Runtime 'none installed'; fi
  else _row 'SDK (latest)' 'not found'; _row Runtime 'not found'; fi
  _row Framework 'n/a (Windows only)'

  echo "$dash"; echo ' NODE.JS, PYTHON 3, JAVA'
  local nd nv py pp p t jv jt jver jven jc jct
  nd="$(_find node | head -n1)"; nv=''; [ -n "$nd" ] && nv="$(_first "$(_run "$nd" --version)")"
  if printf '%s' "$nv" | grep -Eq '^v?[0-9]+\.[0-9]+\.[0-9]+'; then _row Node.js "$(printf '%s' "$nv" | sed -E 's/^v?([0-9]+\.[0-9]+\.[0-9]+).*/\1/')   $nd"; else _row Node.js 'not found'; fi
  py=''; pp=''
  for c in python3 python; do for p in $(_find $c); do t="$(_first "$(_run "$p" --version)")"; if printf '%s' "$t" | grep -Eq '^Python 3\.[0-9]+'; then py="${t#Python }"; pp="$p"; break; fi; done; [ -n "$py" ] && break; done
  if [ -n "$py" ]; then _row 'Python 3' "$py   $pp"; else _row 'Python 3' 'not found'; fi
  jv="$(_find java | head -n1)"; jt=''; [ -n "$jv" ] && jt="$(_run "$jv" -XshowSettings:properties -version)"
  if printf '%s' "$jt" | grep -Eq 'version "[^"]+"'; then
    jver="$(printf '%s\n' "$jt" | sed -nE 's/.*version "([^"]+)".*/\1/p' | head -n1)"; jven="$(printf '%s\n' "$jt" | sed -nE 's/^ *java\.vendor = (.+)$/\1/p' | head -n1 | sed 's/[[:space:]]*$//')"
    if [ -n "$jven" ]; then _row 'Java runtime' "$jver   $jven"; else _row 'Java runtime' "$jver"; fi
  else _row 'Java runtime' 'not found'; fi
  jc="$(_find javac | head -n1)"; jct=''; [ -n "$jc" ] && jct="$(_run "$jc" -version | grep -m1 '^javac ')"
  if printf '%s' "$jct" | grep -Eq '^javac '; then _row 'JDK (javac)' "${jct#javac }"; else _row 'JDK (javac)' 'not found'; fi

  echo "$dash"; echo ' SHELLS'
  local pl psl bs bt oth f s
  pl=''; for p in $(_find pwsh); do t="$(_run "$p" -NoProfile -Command '$PSVersionTable.PSVersion.ToString()')"; t="$(_first "$t")"; printf '%s' "$t" | grep -Eq '^[0-9]+\.[0-9]+' && pl="$pl$t"$'\n'; done
  psl="$(printf '%s' "$pl" | awk 'NF && !s[$0]++' | sort -V | paste -sd, - | sed 's/,/, /g')"
  if [ -n "$psl" ]; then _row PowerShell "$psl"; else _row PowerShell 'not found'; fi
  bs="$(_find bash | head -n1)"; bt=''; [ -n "$bs" ] && bt="$(_first "$(_run "$bs" --version)")"
  if printf '%s' "$bt" | grep -Eq 'version [0-9]'; then _row Bash "$(printf '%s' "$bt" | sed -E 's/.*version ([^ ]+).*/\1/')   $bs"; else _row Bash 'not found'; fi
  oth=''
  for s in zsh fish tcsh ksh dash csh; do
    f="$(_find $s | head -n1)"; [ -z "$f" ] && continue
    [ "$s" = csh ] && printf '%s' "$oth" | grep -q 'tcsh' && continue
    t=''; case "$s" in zsh|fish|tcsh) t="$(_first "$(_run "$f" --version)")" ;; esac
    if printf '%s' "$t" | grep -Eq '[0-9]+\.[0-9]+'; then oth="$oth$s $(printf '%s' "$t" | grep -Eo '[0-9]+\.[0-9]+(\.[0-9]+)*' | head -n1), "; else oth="$oth$s (present), "; fi
  done
  oth="${oth%, }"; if [ -n "$oth" ]; then _row 'Other shells' "$oth"; else _row 'Other shells' 'none found'; fi

  echo "$dash"; echo ' TLS: SCHANNEL AND OPENSSL'
  _row Schannel 'n/a (Windows only)'
  local cands npath known g cfg sdir sec l real pre ld ver lib vendor own role idx rows seen ok4 line
  cands="$(_find openssl)"; npath=$(printf '%s\n' "$cands" | grep -c .)
  known=''; for g in /usr/bin/openssl /usr/local/bin/openssl /usr/local/ssl/bin/openssl /opt/openssl*/bin/openssl /opt/*/bin/openssl /usr/local/openssl*/bin/openssl; do for f in $g; do [ -x "$f" ] && known="$known$f"$'\n'; done; done
  sdir="$(cd "$(dirname "$0")" 2>/dev/null && pwd)"; cfg="$sdir/pki_tools.cnf"
  if [ -r "$cfg" ]; then known="$known$(awk '/^[ \t]*\[/ {sec=$0; gsub(/[ \t\[\]]/,"",sec)} sec=="openssl" && /^[ \t]*Path[ \t]*=/ {sub(/^[^=]*=[ \t]*/,""); sub(/[ \t]+$/,""); print}' "$cfg" | while IFS= read -r l; do [ -x "$l" ] && echo "$l"; done)"$'\n'; fi
  cands="$(printf '%s\n%s\n' "$cands" "$known" | grep .)"
  seen=''; rows=0; idx=0; ok4=0
  while IFS= read -r p; do
    [ -z "$p" ] && continue
    real="$(readlink -f "$p" 2>/dev/null)"; [ -z "$real" ] && real="$p"
    case "$seen" in *"|$real|"*) idx=$((idx+1)); continue ;; esac; seen="$seen|$real|"
    ld=''; pre="$(dirname "$(dirname "$real")")"; [ -n "$pre" ] && [ "$pre" != /usr ] && ld="$pre/lib64:$pre/lib"
    t="$(LD_LIBRARY_PATH="${ld}${ld:+:}${LD_LIBRARY_PATH:-}" _run "$real" version)"
    if ! printf '%s' "$t" | grep -Eq '(OpenSSL|LibreSSL) [0-9]+\.[0-9]+\.[0-9]+'; then idx=$((idx+1)); continue; fi
    lib="$(printf '%s' "$t" | grep -Eo '(OpenSSL|LibreSSL) [0-9]+\.[0-9]+\.[0-9]+[^ ]*' | head -n1)"; ver="${lib#* }"; lib="${lib%% *}"
    if [ "$lib" = LibreSSL ]; then vendor='LibreSSL project'
    else
      own="$(_first "$(dpkg -S "$real" 2>/dev/null)")"
      if printf '%s' "$own" | grep -Eq '^[a-z0-9][A-Za-z0-9.+_-]*(:[a-z0-9]+)?: /'; then vendor="package $(printf '%s' "$own" | sed -E 's/^([^:]+).*/\1/') (dpkg)"
      else own="$(_first "$(rpm -qf "$real" 2>/dev/null)")"
        if [ -n "$own" ] && ! printf '%s' "$own" | grep -Eqi 'not owned|error|No such'; then vendor="package $own (rpm)"; else vendor='built from source code (openssl.org), not a package'; fi
      fi
    fi
    if [ "$rows" = 0 ] && [ "$idx" -lt "$npath" ]; then role=Default; else role=Side; fi
    _row "$role OpenSSL" "$ver   $real"$'\n'"from: $vendor"
    printf '%s' "$ver" | grep -Eq '^[4-9]\.' && ok4=1
    rows=$((rows+1)); idx=$((idx+1))
  done <<< "$cands"
  if [ "$rows" = 0 ]; then _row OpenSSL 'not found'
  elif [ "$ok4" = 1 ]; then _row 'PKI needs' 'OpenSSL 4.x: found'
  else _row 'PKI needs' 'OpenSSL 4.x: NOT found (Install-DevEnvironment can install it)'; fi
  echo "$rule"
  return 0
}
for __pki_a in "$@"; do case "$__pki_a" in --version) pki_version_info; exit $? ;; esac; done
# <<< PKI-VERSION-INFO
VERSION="7.5.3"
set -u

help_pager() {  # help text: one screen at a time on a terminal (Space = next page, q = quit); everything when piped
  if [ -t 1 ] && command -v less >/dev/null 2>&1; then less -FRXK; elif [ -t 1 ] && command -v more >/dev/null 2>&1; then more; else cat; fi
}
usage() {
cat <<'EOT'
====================================================================================================
 remove-pki-ca.sh  -  take a PKI away again that install-pki-ca.sh installed (Linux)
 Version 7.5.3
 Author : Nicko Satria Utama
 Company: Agantra Inovatif OÜ (NextMantra)
 Email  : nicko@nextmantra.com
====================================================================================================
 On a terminal: SPACE = next page, Q = quit.
 Manual : PkiTrustKit-MANUAL.txt     Twin: Remove-PkiCa.ps1 (Windows)
 Needs  : bash, sudo (unless you are root). No package, no password, no other file.

WHAT IT IS
  install-pki-ca.sh wrote a list of everything it installed: /var/lib/pki-trust-kit/installed.tsv.
  It names the root files in the system store (pki-<company>-....crt), the files opened into the
  folder pki/ next to the script, and the Firefox imports (--firefox).
  This script reads the list, removes the files of the PKI(s) you name, then refreshes the system
  store (update-ca-certificates or update-ca-trust).

QUICK START
  1. Look first:        bash remove-pki-ca.sh --list
  2. Test the removal:  bash remove-pki-ca.sh --pki raksaka --check
  3. Remove:            bash remove-pki-ca.sh --pki raksaka
  sudo is called by itself for the system store.

MORE EXAMPLES
  bash remove-pki-ca.sh --pki agantra,raksaka   several companies
  bash remove-pki-ca.sh --all                   EVERYTHING the kit installed (all companies)
  bash remove-pki-ca.sh --org raksaka           no list (or an older kit): remove pki-raksaka-*.crt
                                                from the system store

OPTIONS
  --list              Show the list and stop.
  --pki NAME[,NAME]   The company short name(s) as shown by --list. Every release of it.
  --all               Every PKI in the list.
  --org NAME[,NAME]   By name, without the list: <store>/pki-NAME-*.crt (and the old
                      NAME-pki-*.crt).
  --keep-files        Leave the opened files in the folder pki/. Only the system store is cleaned.
  --check             Show what would be removed. Change nothing.
  --yes               Do not ask "Remove N file(s)?".
  --help, -h          This text.
  --version           Show version, author, OS and tool versions.

EXIT CODES   0 done    1 error    5 this Linux is refused

SUPPORTED
  Ubuntu 24.04 / 26.04 or newer, CentOS Stream 10+, RHEL 10+, Rocky Linux 10+, Oracle Linux 10+,
  SUSE Linux Enterprise 15+, openSUSE 15+. Any other distribution or older version: exit 5,
  nothing is changed.
====================================================================================================
EOT
}

C_OK=""; C_W=""; C_E=""; C_I=""; C_0=""
[ -t 1 ] && { C_OK=$'\033[32m'; C_W=$'\033[33m'; C_E=$'\033[31m'; C_I=$'\033[36m'; C_0=$'\033[0m'; }
info() { printf '%s[INFO]%s %s\n' "$C_I" "$C_0" "$*"; }
ok()   { printf '%s[OK]%s   %s\n' "$C_OK" "$C_0" "$*"; }
warn() { printf '%s[WARN]%s %s\n' "$C_W" "$C_0" "$*" >&2; }
die()  { printf '%s[ERROR]%s %s\n' "$C_E" "$C_0" "$1" >&2; exit "${2:-1}"; }

PKIS=""; ORGS=""; ALL=0; LIST=0; CHECK=0; YES=0; KEEPFILES=0
case "${1:-}" in -h|--help) : ;; *) echo "[INFO] remove-pki-ca.sh version $VERSION" >&2 ;; esac
while [ $# -gt 0 ]; do
  case "$1" in
    --pki) [ $# -ge 2 ] || die "--pki needs a name"; PKIS="$PKIS,$2"; shift 2 ;;
    --org) [ $# -ge 2 ] || die "--org needs a name"; ORGS="$ORGS,$2"; shift 2 ;;
    --all) ALL=1; shift ;;
    --list) LIST=1; shift ;;
    --keep-files) KEEPFILES=1; shift ;;
    --check) CHECK=1; shift ;;
    --yes|-y) YES=1; shift ;;
    -h|--help) usage | help_pager; exit 0 ;;
    *) die "unknown option: $1  (try --help)" ;;
  esac
done
PKIS="$(echo "$PKIS" | tr 'A-Z,;' 'a-z  ' | xargs -n1 2>/dev/null | sort -u | tr '\n' ' ')"
ORGS="$(echo "$ORGS" | tr 'A-Z,;' 'a-z  ' | xargs -n1 2>/dev/null | sort -u | tr '\n' ' ')"

echo "============================================================"
echo " remove-pki-ca.sh - remove PKIs installed by install-pki-ca.sh"
echo " Author : Nicko Satria Utama   Company: Agantra Inovatif OU (NextMantra)   Email: nicko@nextmantra.com"
echo "============================================================"
[ "$(uname -s)" = Linux ] || die "This script is for Linux. On Windows use Remove-PkiCa.ps1." 1

# ---- which Linux? the same rules as install-pki-ca.sh (exit 5 otherwise)
OSREL="${PKI_OS_RELEASE_FILE:-/etc/os-release}"
OS_ID=""; OS_VER=""; OS_PRETTY=""
if [ -r "$OSREL" ]; then OS_ID="$(. "$OSREL"; echo "${ID:-}")"; OS_VER="$(. "$OSREL"; echo "${VERSION_ID:-}")"; OS_PRETTY="$(. "$OSREL"; echo "${PRETTY_NAME:-$NAME}")"; fi
OS_MAJOR="${OS_VER%%.*}"; case "$OS_MAJOR" in ''|*[!0-9]*) OS_MAJOR=0 ;; esac
OS_OK=0
case "$OS_ID" in
  ubuntu)                  [ "$OS_MAJOR" -ge 24 ] && OS_OK=1 ;;
  centos|rhel|rocky|ol)    [ "$OS_MAJOR" -ge 10 ] && OS_OK=1 ;;
  sles|sles_sap|sled|opensuse-leap) [ "$OS_MAJOR" -ge 15 ] && OS_OK=1 ;;
  opensuse-tumbleweed)     OS_OK=1 ;;
esac
[ "$OS_OK" = 1 ] || die "This system is '${OS_PRETTY:-unknown}' (ID=${OS_ID:-?} VERSION_ID=${OS_VER:-?}): NOT supported. Nothing was changed.
        Supported: Ubuntu 24.04 / 26.04 or newer; CentOS Stream 10+; RHEL 10+; Rocky Linux 10+; Oracle Linux 10+; SUSE Linux Enterprise 15+; openSUSE 15+ (Leap 15, 16 ..., Tumbleweed)." 5

STATE_DIR="${PKI_KIT_STATE_DIR:-/var/lib/pki-trust-kit}"
REG="$STATE_DIR/installed.tsv"
# the anchor folder and update command: from the list (written by the installer), else from this machine
UPDATE=""; ANCHOR=""
if [ -f "$REG" ]; then
  while IFS=$'\t' read -r k a b; do [ "$k" = "#update" ] && { UPDATE="$a"; ANCHOR="$b"; }; done < <(grep '^#update' "$REG" | tr -d '\r')
fi
if [ -z "$UPDATE" ]; then
  OSLIKE=""; [ -r /etc/os-release ] && OSLIKE="$(. /etc/os-release; echo "${ID_LIKE:-}")"
  case " $OS_ID $OSLIKE " in
    *" ubuntu "*|*" debian "*) ANCHOR="/usr/local/share/ca-certificates"; UPDATE="update-ca-certificates" ;;
    *" rhel "*|*" fedora "*|*" centos "*) ANCHOR="/etc/pki/ca-trust/source/anchors"; UPDATE="update-ca-trust extract" ;;
    *) ANCHOR="/etc/pki/trust/anchors"; UPDATE="update-ca-certificates" ;;
  esac
fi
ANCHOR="${PKI_ANCHOR_DIR:-$ANCHOR}"; UPDATE="${PKI_UPDATE_CMD:-$UPDATE}"
SUDO=""
if [ "$(id -u)" != 0 ] && [ -z "${PKI_ANCHOR_DIR:-}" ] && [ "$LIST" = 0 ] && [ "$CHECK" = 0 ]; then command -v sudo >/dev/null 2>&1 && SUDO="sudo" || die "root or sudo is needed for the system certificate store."; fi

# ---- the list
ROWS=()   # pki<TAB>release<TAB>kind<TAB>path<TAB>name
if [ -f "$REG" ]; then while IFS= read -r l; do ROWS+=("$l"); done < <(grep -v '^#' "$REG" | tr -d '\r' | grep -v '^$'); fi
if [ "$LIST" = 1 ] || { [ "$ALL" = 0 ] && [ -z "${PKIS// /}" ] && [ -z "${ORGS// /}" ]; }; then
  if [ "${#ROWS[@]}" -eq 0 ]; then info "The list is empty ($REG): this kit installed nothing here (or it was removed). Use --org NAME to remove by name."
  else
    info "${#ROWS[@]} entries in $REG:"
    printf '%s\n' "${ROWS[@]}" | cut -f1 | sort -u | while read -r pk; do
      rels="$(printf '%s\n' "${ROWS[@]}" | awk -F'\t' -v p="$pk" '$1==p && $2!="" {print $2}' | sort -u | tr '\n' ' ')"
      nroot="$(printf '%s\n' "${ROWS[@]}" | awk -F'\t' -v p="$pk" '$1==p && $3=="anchor"' | wc -l)"
      info "  $pk: $nroot root(s) in the system store; PKI folders: ${rels:-?}"
      printf '%s\n' "${ROWS[@]}" | awk -F'\t' -v p="$pk" '$1==p && $3=="anchor" {print "        " $4}'
    done
  fi
  [ "$LIST" = 1 ] || info "Say what to remove:  --pki NAME   or   --all   (or --org NAME).  --check only shows."
  exit 0
fi

# ---- what to remove
TODO=()   # kind<TAB>path<TAB>name
if [ -n "${PKIS// /}" ]; then
  for want in $PKIS; do
    n=0
    for r in "${ROWS[@]}"; do IFS=$'\t' read -r pk rel kind path name _x <<<"$r"; [ "$(echo "$pk" | tr 'A-Z' 'a-z')" = "$want" ] && { TODO+=("$kind"$'\t'"$path"$'\t'"$name"); n=$((n+1)); }; done
    [ "$n" -gt 0 ] || { known="$(printf '%s\n' "${ROWS[@]:-}" | cut -f1 | sort -u | tr '\n' ' ')"; die "'$want' is not in the list. Known: ${known:-(empty)}"; }
  done
fi
if [ "$ALL" = 1 ]; then for r in "${ROWS[@]}"; do IFS=$'\t' read -r pk rel kind path name _x <<<"$r"; TODO+=("$kind"$'\t'"$path"$'\t'"$name"); done; fi
if [ -n "${ORGS// /}" ]; then
  for want in $ORGS; do for f in "$ANCHOR/pki-$want"-*.crt "$ANCHOR/$want"-pki-*.crt; do [ -f "$f" ] && TODO+=("anchor"$'\t'"$f"$'\t'"$(basename "$f")"); done; done
fi
[ "${#TODO[@]}" -gt 0 ] || { info "Nothing to remove."; exit 0; }
info "${#TODO[@]} item(s) to remove:"
for t in "${TODO[@]}"; do IFS=$'\t' read -r kind path name <<<"$t"; info "  [$kind] $path"; done
if [ "$CHECK" = 1 ]; then ok "Check finished: nothing was changed."; exit 0; fi
if [ "$YES" = 0 ]; then
  [ -t 0 ] || die "Not a terminal: add --yes to remove without asking."
  read -r -p "Remove ${#TODO[@]} item(s)? (y/N) " a; case "$a" in y|Y|yes|YES) : ;; *) info "Cancelled, nothing was changed."; exit 0 ;; esac
fi

nanchor=0; nfile=0; nff=0; dirs=()
for t in "${TODO[@]}"; do
  IFS=$'\t' read -r kind path name <<<"$t"
  case "$kind" in
    anchor) if [ -f "$path" ]; then $SUDO rm -f "$path" && { nanchor=$((nanchor+1)); ok "removed from the system store: $(basename "$path")"; }; fi ;;
    file)   if [ "$KEEPFILES" = 0 ] && [ -f "$path" ]; then rm -f "$path" 2>/dev/null && { nfile=$((nfile+1)); dirs+=("$(dirname "$path")"); }; fi ;;
    firefox) command -v certutil >/dev/null 2>&1 && certutil -D -d "sql:$path" -n "$name" >/dev/null 2>&1 && { nff=$((nff+1)); ok "removed from Firefox profile $(basename "$path"): $name"; } ;;
  esac
done
# empty folders of the opened package go too
for d in $(printf '%s\n' "${dirs[@]:-}" | sort -u | awk '{print length, $0}' | sort -rn | cut -d' ' -f2-); do
  while [ -n "$d" ] && [ -d "$d" ] && [ -z "$(ls -A "$d" 2>/dev/null)" ] && case "$d" in */pki|*/pki/*) true ;; *) false ;; esac; do rmdir "$d" 2>/dev/null || break; d="$(dirname "$d")"; done
done
if [ "$nanchor" -gt 0 ]; then
  info "Running: $UPDATE"
  $SUDO $UPDATE 2>&1 | sed 's/^/        /'
fi
# update the list: remove the rows of what was removed
if [ -f "$REG" ]; then
  tmp="$(mktemp "${TMPDIR:-/tmp}/pki-reg.XXXXXX")"
  { grep '^#' "$REG"
    grep -v '^#' "$REG" | tr -d '\r' | while IFS=$'\t' read -r a b c d e g; do
      gone=0; for t in "${TODO[@]}"; do IFS=$'\t' read -r tk tp tn <<<"$t"; [ "$tp" = "$d" ] && [ "$tk" = "$c" ] && gone=1; done
      [ "$gone" = 1 ] || printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$a" "$b" "$c" "$d" "$e" "$g"
    done; } > "$tmp"
  if [ -z "$(grep -v '^#' "$tmp")" ]; then $SUDO rm -f "$REG"; $SUDO rmdir "$STATE_DIR" 2>/dev/null; else $SUDO cp -f "$tmp" "$REG"; fi
  rm -f "$tmp"
fi
# nothing of the kit is left: the information files of the opened package and the empty folders go as well
if [ "$KEEPFILES" = 0 ] && [ ! -f "$REG" ]; then
  for t in "${TODO[@]}"; do IFS=$'\t' read -r kind path name <<<"$t"; [ "$kind" = file ] && case "$path" in */pki/ca/*) echo "${path%/ca/*}" ;; esac; done | sort -u | while read -r base; do
    [ -d "$base" ] || continue
    rm -f "$base/README.txt" "$base/SHA256SUMS" "$base/certpack.json" "$base/certpack.tsv" 2>/dev/null
    find "$base" -depth -type d -empty -delete 2>/dev/null
  done
fi
# read back
left=0; for t in "${TODO[@]}"; do IFS=$'\t' read -r kind path name <<<"$t"; [ "$kind" = anchor ] && [ -f "$path" ] && { left=$((left+1)); warn "still there: $path"; }; done
[ "$left" = 0 ] || die "$left file(s) could not be removed from $ANCHOR."
ok "Removed $nanchor root(s) from the system store, $nfile opened file(s)$( [ "$nff" -gt 0 ] && echo ", $nff Firefox import(s)"). Restart browsers / tools."
exit 0
